# Rebuild Appendix C15-C20 from fresh H3 fits.
.root<-Sys.getenv("REPLICATION_ROOT",unset="");if(!nzchar(.root)){.a<-grep("^--file=",commandArgs(FALSE),value=TRUE);.root<-file.path(dirname(normalizePath(sub("^--file=","",.a[1]))),"..","..")};source(file.path(.root,"code","R","_table_helpers.R"));P<-replication_bootstrap();spec<-function(n)file.path(P$code,"specs","appendix",n);out<-function(n)file.path(P$appendix_tables,n)
m<-read_models(P,"H3");s<-read.csv(file.path(P$estimates,"H3_results.csv"));emit<-function(name,ids,n)write_body(hydrate_scaffold(spec(name),m[ids],s),out(name),n)
