add<-read.csv(file.path(P$estimates,"H3_table4_additional_moderators_results.csv"));ids<-c("ADD1W","ADD1F","ADD2W","ADD2F");add<-add[match(ids,add$model),];if(any(is.na(add$model)))stop("C20 extension rows missing.",call.=FALSE)
pair<-function(b,p,se)c(fmt_coef(b,p),fmt_se(se));rows<-list();push<-function(label,v)rows[[length(rows)+1L]]<<-c(label,v)
cells<-lapply(seq_len(nrow(add)),function(i)list(eng=pair(add$beta_eng_c[i],add$p_eng_c[i],add$se_eng_c[i]),mod=pair(add$beta_mod_c[i],add$p_mod_c[i],add$se_mod_c[i]),int=pair(add$beta_int[i],add$p_int[i],add$se_int[i])))
push("Proportion of English-Language Signs (centered)",vapply(cells,function(x)x$eng[1],character(1)));push("",vapply(cells,function(x)x$eng[2],character(1)));push("V-Dem Political Liberty (centered)",c(cells[[1]]$mod[1],cells[[2]]$mod[1],"",""));push("",c(cells[[1]]$mod[2],cells[[2]]$mod[2],"",""));push("V-Dem Freedom of Association thick (centered)",c("","",cells[[3]]$mod[1],cells[[4]]$mod[1]));push("",c("","",cells[[3]]$mod[2],cells[[4]]$mod[2]));push("Eng x Political Liberty",c(cells[[1]]$int[1],cells[[2]]$int[1],"",""));push("",c(cells[[1]]$int[2],cells[[2]]$int[2],"",""));push("Eng x Freedom of Association",c("","",cells[[3]]$int[1],cells[[4]]$int[1]));push("",c("","",cells[[3]]$int[2],cells[[4]]$int[2]));push("",rep("",4));push("Observations",as.character(add$N));push("EPV (* = <5)",ifelse(is.na(add$epv),"",sprintf("%.1f%s",add$epv,ifelse(add$epv<5,"*",""))))
